# Homebrew Formula for GitCode CLI
#
# This is a local reference copy. The live formula is generated by GoReleaser
# (see .goreleaser.yaml `brews:`) and pushed to atomgit-cli/homebrew-tap by the
# release workflow (see .github/workflows/release.yml `brew` job).
#
# Install with:
#   brew install atomgit-cli/homebrew-tap/gc
#
# The sha256 and version fields here are placeholders; GoReleaser injects the
# real values from the published release artifacts. The DSL (on_intel/on_arm vs
# Hardware::CPU checks) may also differ from the generated result; always treat
# dist/homebrew/gc.rb as the source of truth.

class Gc < Formula
  desc "GitCode CLI - Command line tool for GitCode"
  homepage "https://gitcode.com/atomgit-cli/cli"
  version "0.1.0"
  license "MIT"

  on_macos do
    on_intel do
      url "https://github.com/atomgit-cli/cli/releases/download/v#{version}/gc_#{version}_darwin_amd64.tar.gz"
      sha256 ""
    end
    on_arm do
      url "https://github.com/atomgit-cli/cli/releases/download/v#{version}/gc_#{version}_darwin_arm64.tar.gz"
      sha256 ""
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/atomgit-cli/cli/releases/download/v#{version}/gc_#{version}_linux_amd64.tar.gz"
      sha256 ""
    end
    on_arm do
      url "https://github.com/atomgit-cli/cli/releases/download/v#{version}/gc_#{version}_linux_arm64.tar.gz"
      sha256 ""
    end
  end

  def install
    bin.install "gc"
    bin.install_symlink "gc" => "gitcode"
    bash_completion.install "completions/gc.bash" => "gc"
    zsh_completion.install "completions/gc.zsh" => "_gc"
    fish_completion.install "completions/gc.fish"
  end

  test do
    assert_match "gc version", shell_output("#{bin}/gc version")
  end
end
